package com.ppms.admin.service;
import com.ppms.admin.api.workforce.WorkforceDtos.*;import com.ppms.admin.domain.workforce.ShiftTemplate;import com.ppms.admin.repositories.workforce.ShiftTemplateRepository;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service @RequiredArgsConstructor public class ShiftTemplateService {private final ShiftTemplateRepository repository;@Transactional public ShiftTemplateDto create(ShiftTemplateRequest r){ShiftTemplate s=new ShiftTemplate();s.setSiteId(r.siteId());s.setCode(r.code());s.setStartTime(r.startTime());s.setEndTime(r.endTime());s.setBreakMinutes(r.breakMinutes());s.setColor(r.color());return dto(repository.save(s));}@Transactional(readOnly=true)public List<ShiftTemplateDto> list(UUID siteId){return(siteId==null?repository.findAll():repository.findBySiteId(siteId)).stream().map(this::dto).toList();}private ShiftTemplateDto dto(ShiftTemplate s){return new ShiftTemplateDto(s.getId(),s.getSiteId(),s.getCode(),s.getStartTime(),s.getEndTime(),s.getBreakMinutes(),s.getColor());}}
